// EVERLAST — The Catalogue Photo of an Impossible Gadget.
// Entry program for make.fun bounty the-catalogue-photo-of-an-2-20261121-0341.
// Writes the catalogue photograph to /output/entry.png. No network, Node 22, stdlib only.
import { mkdirSync, writeFileSync } from "node:fs";

// The catalogue image (819x1024, JPEG bytes), embedded so the program is self-contained.
const IMAGE_B64 = "";

const outDir = process.env.OUTPUT_DIR ?? "/output";
mkdirSync(outDir, { recursive: true });
writeFileSync(outDir + "/entry.png", Buffer.from(IMAGE_B64, "base64"));
console.log("wrote " + outDir + "/entry.png");
